        ("alpha", "1"),
        ("mike", "0"),
    ] {
        let run = run_br(
            &workspace,
            ["create", title, "--priority", priority],
            "create",
        );
        assert!(run.status.success(), "create {title} failed: {}", run.stderr);
    }

    let titles = list_field(
        &workspace,
        &["list", "--sort", "priority,title", "--json"],
        "title",
        "list priority,title",
    );
    let titles: Vec<String> = titles
        .iter()
        .map(|t| t.trim_matches('"').to_string())
        .collect();

