/// Every `(table, column)` pair in the schema that stores an issue ID.
///
/// `tests/storage/rename_coverage.rs` walks `PRAGMA table_info` and fails if a
/// table gains an ID-bearing column missing from this list — add the pair rather
/// than weakening that test.
pub(crate) const ID_BEARING_COLUMNS: &[(&str, &str)] = &[
    ("dependencies", "issue_id"),
    // No foreign key on this one (schema.rs:132, kept so `external:` refs can
    // dangle), so a missed rewrite here fails silently rather than loudly.
    ("dependencies", "depends_on_id"),
    ("labels", "issue_id"),
    ("comments", "issue_id"),
    ("dirty_issues", "issue_id"),
    ("export_hashes", "issue_id"),
    ("blocked_issues_cache", "issue_id"),
    ("child_counters", "parent_id"),
    ("close_metadata", "issue_id"),
];

/// Move one issue from `old_id` to `new_id`, rewriting every reference.
///
/// One node only — subtree cascade belongs to [`SqliteStorage::rename_issue`].
///
/// The caller must already hold a write transaction with
/// `PRAGMA defer_foreign_keys = ON`. Without it the `issues` update fails with
/// `FOREIGN KEY constraint failed`: no FK in this schema declares `ON UPDATE`,
/// and the child rows still point at `old_id` at that moment.
fn rewrite_issue_id(conn: &Connection, old_id: &str, new_id: &str) -> Result<()> {
    conn.execute_with_params(
        "UPDATE issues SET id = ? WHERE id = ?",
        &[SqliteValue::from(new_id), SqliteValue::from(old_id)],
    )?;

    for (table, column) in ID_BEARING_COLUMNS {
        // Table and column names come from the compile-time slice above, never
        // from user input, so formatting them into the SQL is sound.
        conn.execute_with_params(
            &format!("UPDATE OR IGNORE {table} SET {column} = ? WHERE {column} = ?"),
            &[SqliteValue::from(new_id), SqliteValue::from(old_id)],
        )?;
    }

    Ok(())
}
```

**`UPDATE OR IGNORE`, not plain `UPDATE`.** `dependencies` has
`PRIMARY KEY (issue_id, depends_on_id)` and `labels` has
`PRIMARY KEY (issue_id, label)`, so a rewrite can collide with an existing row.
`OR IGNORE` drops the redundant duplicate rather than aborting the whole rename.

- [ ] **Step 4: Implement the public entry point**

```rust
    /// Move `old_id` to `new_id`, carrying the entire subtree beneath it.
    ///
    /// Renaming `bd-p.1` to `bd-q.7` also moves `bd-p.1.1` to `bd-q.7.1`, at
    /// every depth and in every status. The whole move is one transaction: a
    /// failure at any node leaves the tree exactly as it was.
    ///
    /// Does **not** touch `former_ids` or write a tombstone — Task 6 layers
    /// those on top.
    ///
    /// # Errors
    ///
    /// - `IssueNotFound` if `old_id` does not exist
    /// - `validation` if `new_id` is already taken
    /// - any database error, with the transaction rolled back
    pub fn rename_issue(&mut self, old_id: &str, new_id: &str, actor: &str) -> Result<()> {
        if !self.id_exists(old_id)? {
            return Err(BeadsError::IssueNotFound { id: old_id.to_string() });
        }
        if self.id_exists(new_id)? {
            return Err(BeadsError::validation(
                "new_id",
                format!("{new_id} already exists"),
            ));
        }

        // Deepest-first, so renaming a node never invalidates an ID still
        // queued behind it.
        let descendants = self.descendant_ids(old_id)?;

        self.with_write_transaction(|storage| {
            // Transaction-scoped and self-resetting, unlike the global
            // `PRAGMA foreign_keys = OFF` toggle at schema.rs:930. Needed
            // because the issues row moves before its referencing rows do.
            storage.conn.execute("PRAGMA defer_foreign_keys = ON")?;

            for descendant in &descendants {
                // `bd-p.1.1` under a `bd-p.1` -> `bd-q.7` move becomes
                // `bd-q.7` + `.1` — splice the new prefix onto the tail.
                let suffix = descendant
                    .strip_prefix(old_id)
                    .ok_or_else(|| BeadsError::validation(
                        "descendant",
                        format!("{descendant} is not beneath {old_id}"),
                    ))?;
                rewrite_issue_id(&storage.conn, descendant, &format!("{new_id}{suffix}"))?;
            }

            rewrite_issue_id(&storage.conn, old_id, new_id)?;

            storage.mark_dirty_in_transaction(new_id)?;
            storage.record_history_in_transaction(
                new_id,
                "renamed",
                Some(old_id),
                Some(new_id),
                actor,
            )?;
            Ok(())
        })
    }
```

Note the descendants are renamed **before** the node itself. Their old IDs are
still valid at that point; renaming the parent first would strand them.

