```rust
/// Attach `issue_id` beneath `parent_id`, renumbering it to match.
///
/// The invariant this project maintains is that a dotted prefix always names the
/// real parent. Setting a parent therefore always moves the ID: an issue that
/// kept its old ID here would be claiming a parent it no longer has, which is
/// exactly the divergence `close` trips over.
///
/// Returns the new ID.
///
/// # Errors
///
/// Propagates storage failures and any collision from `rename_issue`.
pub(crate) fn attach_to_parent(
    storage: &mut SqliteStorage,
    issue_id: &str,
    parent_id: &str,
    actor: &str,
) -> crate::Result<String> {
    let next = storage.next_child_number(parent_id)?;
    let new_id = crate::util::id::child_id(parent_id, next);

    storage.add_dependency(issue_id, parent_id, "parent-child", actor)?;
    storage.rename_issue(issue_id, &new_id, actor)?;

    Ok(new_id)
}
